import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
dfs = {}
for i in range(1, 5):
    try:
        df = pd.read_csv(f"experiment_{i}_csv")
        dfs[i] = df
        print(f"\n=== Exp {i} columns: {list(df.columns)} ===")
        print(f"Shape: {df.shape}")
        print(df.head(3))

        # Correlate available numeric columns with ReadmissionRate
        if 'ReadmissionRate' in df.columns:
            for col in df.select_dtypes(include='number').columns:
                if col != 'ReadmissionRate' and df[col].notna().sum() == df['ReadmissionRate'].notna().sum():
                    r, p = stats.pearsonr(df[col], df['ReadmissionRate'])
                    print(f"  {col} vs ReadmissionRate: r={r:.3f}, p={p:.2e}")
    except Exception as e:
        print(f"Exp {i} error: {e}")
